      "title": "Altered and Duplicate Shipping Receipt",
      "claim": "Document D12 is an identical duplicate of D09 (receipt GHN-2231 with identical airway bills, weights, total fee of 159,000 VND, and cashier NV0502), where the date has been altered from 11/02/2026 to 11/03/2026.",
      "severity": "critical"
    },
    {
      "title": "Inconsistent Seller Profile Information",
      "claim": "Document D04 displays the shop title 'Linh Fashion VN' and an unexplained dip to 9,800 followers, conflicting with 'Linh Fashion Official' and 12,900 to 14,200 followers across the other dashboard submissions.",
      "severity": "high"
    },
    {
      "title": "Substantial Unsecured Loan Request Relative to Turnover",
      "claim": "The requested facility of 150,000,000 VND exceeds 2.5 times the monthly gross sales (averaging ~53,000,000 VND), representing high leverage for an uncollateralized facility.",
      "severity": "medium"
    }
  ]
